/**
 * Stage 5 — verifies the 7-day trial lifecycle against Stripe TEST MODE using
 * test clocks, exercising the same StripeService calls the app makes.
 *
 * Each scenario gets its own test clock; clocks (and their customers and
 * subscriptions) are deleted at the end. Real webhook payloads generated by
 * each scenario are also fed through StripeWebhookService to confirm our
 * parser extracts the fields the jobs depend on.
 *
 * Usage: npm run verify:trial        (refuses to run with a live key)
 */
import 'dotenv/config';
import Stripe from 'stripe';
import { ConfigService } from '@nestjs/config';
import { StripeService } from 'src/modules/stripe/services/stripe.service';
import {
  StripeWebhookService,
  type StripeWebhookEvent,
} from 'src/modules/stripe/webhooks/stripe-webhook.service';
import type { RedisService } from 'src/modules/redis/services/redis.service';
import type { AgendaService } from 'src/modules/agenda/services/agenda.service';
import { TRIAL_PERIOD_DAYS } from 'src/common/constants/subscription-features.constants';

const DAY = 86_400;
const HOUR = 3_600;

interface Check {
  scenario: string;
  check: string;
  pass: boolean;
  detail: string;
}

const checks: Check[] = [];
const record = (scenario: string, check: string, pass: boolean, detail = '') =>
  checks.push({ scenario, check, pass, detail });

const secretKey = process.env.STRIPE_SECRET_KEY ?? '';
const priceId = process.env.STRIPE_PRICE_STARTER_MONTHLY ?? '';
if (!secretKey.startsWith('sk_test_')) {
  console.error('Refusing to run: STRIPE_SECRET_KEY must be a test-mode key.');
  process.exit(1);
}
if (!priceId) {
  console.error('STRIPE_PRICE_STARTER_MONTHLY is not set.');
  process.exit(1);
}

const stripe = new Stripe(secretKey, { apiVersion: '2026-05-27.dahlia' });
const config = { get: (key: string) => process.env[key] } as ConfigService;
const app = new StripeService(config);
const clocks: string[] = [];

async function advanceTo(clockId: string, frozenTime: number): Promise<void> {
  await stripe.testHelpers.testClocks.advance(clockId, {
    frozen_time: frozenTime,
  });
  for (let i = 0; i < 90; i++) {
    const clock = await stripe.testHelpers.testClocks.retrieve(clockId);
    if (clock.status === 'ready') return;
    if (clock.status === 'internal_failure') {
      throw new Error(`Test clock ${clockId} failed to advance`);
    }
    await new Promise((r) => setTimeout(r, 2000));
  }
  throw new Error(`Test clock ${clockId} did not finish advancing`);
}

async function setup(name: string, paymentMethod?: string) {
  const now = Math.floor(Date.now() / 1000);
  const clock = await stripe.testHelpers.testClocks.create({
    frozen_time: now,
    name: `servixos-verify-${name}`,
  });
  clocks.push(clock.id);
  const customer = await stripe.customers.create({
    email: `verify+${name}@servixos.test`,
    test_clock: clock.id,
    metadata: { verification: 'trial-lifecycle' },
  });
  if (paymentMethod) {
    await app.attachPaymentMethod(customer.id, paymentMethod);
  }
  const subscription = await app.createSubscription(
    customer.id,
    priceId,
    { businessId: `verify-${name}` },
    `verify:${name}:${clock.id}`,
    { cancelIfNoPaymentMethod: true },
  );
  return { clock, customer, subscription, start: now };
}

async function invoicesFor(customerId: string) {
  return (await stripe.invoices.list({ customer: customerId, limit: 20 }))
    .data;
}

/** Feeds this customer's real webhook events through our parser and returns the job payloads it produced. */
async function parseEvents(customerId: string, since: number) {
  const dispatched: { job: string; data: Record<string, unknown> }[] = [];
  const parser = new StripeWebhookService(
    { setIfAbsent: () => Promise.resolve(true) } as unknown as RedisService,
    {
      now: (job: string, data: Record<string, unknown>) => {
        dispatched.push({ job, data });
        return Promise.resolve();
      },
    } as unknown as AgendaService,
  );
  const events = await stripe.events.list({
    created: { gte: since - 60 },
    limit: 100,
  });
  for (const event of events.data) {
    const object = event.data.object as { customer?: unknown };
    if (object.customer !== customerId) continue;
    await parser.handle(event as unknown as StripeWebhookEvent);
  }
  return dispatched;
}

async function scenarioTrialAndFirstCharge(expectedAmount: number) {
  const name = 'first-charge';
  const { clock, customer, subscription, start } = await setup(
    name,
    'pm_card_visa',
  );
  const trialEnd = subscription.trial_end ?? 0;

  record(name, 'trial starts on subscribe', subscription.status === 'trialing', subscription.status);
  record(
    name,
    `trial lasts ${TRIAL_PERIOD_DAYS} days`,
    trialEnd - start === TRIAL_PERIOD_DAYS * DAY,
    `${(trialEnd - start) / DAY} days`,
  );
  const duringTrial = (await invoicesFor(customer.id)).filter(
    (i) => i.amount_paid > 0,
  );
  record(name, 'no charge during the trial', duringTrial.length === 0, `${duringTrial.length} paid invoices`);

  await advanceTo(clock.id, trialEnd + 2 * HOUR);
  await advanceTo(clock.id, trialEnd + DAY);
  const after = await stripe.subscriptions.retrieve(subscription.id);
  const paid = (await invoicesFor(customer.id)).filter((i) => i.amount_paid > 0);
  record(name, 'subscription active after trial', after.status === 'active', after.status);
  record(
    name,
    'first charge at the disclosed price',
    paid.length === 1 && paid[0].amount_paid === expectedAmount,
    paid.map((i) => `${i.amount_paid} ${i.currency}`).join(', ') || 'no paid invoice',
  );
  record(
    name,
    'first invoice dated at trial end',
    paid.length === 1 && Math.abs(paid[0].created - trialEnd) <= 2 * HOUR,
    paid[0] ? `${(paid[0].created - trialEnd) / HOUR}h from trial end` : '-',
  );

  const jobs = await parseEvents(customer.id, start);
  const succeeded = jobs.find((j) => j.job === 'subscription:payment:succeeded' && Number(j.data.amountPaid) > 0);
  record(name, 'webhook parser: payment_succeeded dispatched', !!succeeded, succeeded ? 'yes' : 'missing');
  record(name, 'webhook parser: subscriptionId extracted', !!succeeded?.data.subscriptionId, String(succeeded?.data.subscriptionId ?? ''));
  record(name, 'webhook parser: priceId extracted', succeeded?.data.priceId === priceId, String(succeeded?.data.priceId ?? 'null'));
  record(
    name,
    'webhook parser: new period end is one interval after trial end',
    after.items.data[0]?.current_period_end === Number(succeeded?.data.periodEnd),
    `${(Number(succeeded?.data.periodEnd) - trialEnd) / DAY} days after trial end`,
  );
  const trialEnding = jobs.find((j) => j.job === 'subscription:trial:ending');
  record(name, 'webhook parser: trial_will_end dispatched', !!trialEnding, trialEnding ? 'yes' : 'missing');
}

async function scenarioFailedPayment(name: string, paymentMethod: string) {
  let setupResult: Awaited<ReturnType<typeof setup>>;
  try {
    setupResult = await setup(name, paymentMethod);
  } catch (err) {
    if (!(err instanceof Stripe.errors.StripeCardError)) throw err;
    record(name, 'card rejected when added (before any trial)', true, `attach failed: ${err.code}`);
    return;
  }
  const { clock, customer, subscription, start } = setupResult;
  const trialEnd = subscription.trial_end ?? 0;
  await advanceTo(clock.id, trialEnd + 2 * HOUR);
  await advanceTo(clock.id, trialEnd + DAY);

  const after = await stripe.subscriptions.retrieve(subscription.id);
  const paid = (await invoicesFor(customer.id)).filter((i) => i.amount_paid > 0);
  record(name, 'no money collected', paid.length === 0, `${paid.length} paid invoices`);
  record(
    name,
    'subscription not active after failed charge',
    after.status !== 'active',
    after.status,
  );
  const open = (await invoicesFor(customer.id)).find((i) => i.status === 'open');
  try {
    const { clientSecret } = await app.getInvoicePaymentClientSecret(open?.id ?? '');
    record(name, 'pay-now returns a client secret for the open invoice', clientSecret.includes('_secret_'), 'ok');
  } catch (err) {
    record(name, 'pay-now returns a client secret for the open invoice', false, err instanceof Error ? err.message : String(err));
  }

  const jobs = await parseEvents(customer.id, start);
  const failed = jobs.find((j) => j.job === 'subscription:payment:failed');
  record(name, 'webhook parser: payment_failed dispatched', !!failed, failed ? 'yes' : 'missing');
  record(name, 'webhook parser: subscriptionId extracted', !!failed?.data.subscriptionId, String(failed?.data.subscriptionId ?? ''));
}

async function scenarioCancelBeforeTrialEnd() {
  const name = 'cancel-in-trial';
  const { clock, customer, subscription, start } = await setup(name, 'pm_card_visa');
  const trialEnd = subscription.trial_end ?? 0;

  await advanceTo(clock.id, start + 3 * DAY);
  await app.cancelSubscription(subscription.id, true, `verify-cancel:${clock.id}`);
  await advanceTo(clock.id, trialEnd + DAY);

  const after = await stripe.subscriptions.retrieve(subscription.id);
  const paid = (await invoicesFor(customer.id)).filter((i) => i.amount_paid > 0);
  record(name, 'canceled at trial end', after.status === 'canceled', after.status);
  record(name, 'never charged', paid.length === 0, `${paid.length} paid invoices`);
  const jobs = await parseEvents(customer.id, start);
  const canceled = jobs.find((j) => j.job === 'subscription:canceled');
  record(name, 'webhook parser: subscription deleted dispatched', !!canceled, canceled ? 'yes' : 'missing');
}

async function scenarioNoPaymentMethod() {
  const name = 'no-card';
  const { clock, customer, subscription } = await setup(name);
  const trialEnd = subscription.trial_end ?? 0;
  await advanceTo(clock.id, trialEnd + DAY);

  const after = await stripe.subscriptions.retrieve(subscription.id);
  const paid = (await invoicesFor(customer.id)).filter((i) => i.amount_paid > 0);
  record(name, 'canceled when trial ends without a card', after.status === 'canceled', after.status);
  record(name, 'never charged', paid.length === 0, `${paid.length} paid invoices`);
}

async function main() {
  const price = await stripe.prices.retrieve(priceId);
  const expectedAmount = price.unit_amount ?? -1;
  console.log(`Verifying against price ${priceId} (${expectedAmount} ${price.currency}/${price.recurring?.interval})\n`);

  const scenarios: [string, () => Promise<void>][] = [
    ['first-charge', () => scenarioTrialAndFirstCharge(expectedAmount)],
    ['failed-payment', () => scenarioFailedPayment('failed-payment', 'pm_card_chargeCustomerFail')],
    ['expired-card', () => scenarioFailedPayment('expired-card', 'pm_card_chargeDeclinedExpiredCard')],
    ['cancel-in-trial', scenarioCancelBeforeTrialEnd],
    ['no-card', scenarioNoPaymentMethod],
  ];

  try {
    // Scenarios are independent (one clock each), so run them concurrently
    const results = await Promise.allSettled(scenarios.map(([, run]) => run()));
    results.forEach((r, i) => {
      if (r.status === 'rejected') {
        record(scenarios[i][0], 'scenario completed', false, r.reason instanceof Error ? r.reason.message : String(r.reason));
      }
    });
  } finally {
    await Promise.allSettled(clocks.map((id) => stripe.testHelpers.testClocks.del(id)));
  }

  console.table(checks.map((c) => ({ ...c, pass: c.pass ? 'PASS' : 'FAIL' })));
  const failed = checks.filter((c) => !c.pass).length;
  console.log(`\n${checks.length - failed}/${checks.length} checks passed`);
  process.exit(failed ? 1 : 0);
}

void main();
